    structures_short: "yapı",
    /* Motif sorgu paneli. Aşağıdaki skorlar farklı soruları yanıtlar ve hiçbir zaman tek bir sayıda
       birleştirilmez; her biri kendi açıklamasını metricHelp() ile taşır. */
    mq_intro: "Genel bir konumda bir kalıntı isteyin ve bunu hangi reseptörlerin taşıdığını okuyun. Birim çökeltme değil reseptördür: seksen kez çözülmüş bir reseptör bir kez sayılır ve aileler, reseptörlerinin medyanı üzerinden sıralanır; böylece fazla temsil edilen bir reseptör ailesinin tamamı adına konuşamaz. Skorlanan kalıntı her zaman reseptörün kendi yabanıl tipidir; çökeltilen konstrüktün değiştirildiği yerlerde bu durum skorlanmaz, işaretlenir.",
    mq_query_placeholder: "3x50R 6x30E",
    mq_query_hint: "Konum ve kalıntı; örneğin 3x50R. Bir konumda birden çok kalıntı «ya da» olarak okunur: 6x30DE. Boşluk, virgül ya da + ile ayırın.",
    mq_seed_hint: "Sorguyu bu motifin konumlarıyla, uzlaşı kalıntıları kullanılarak doldur",
    mq_query_label: "SORGU",
    mq_query_empty: "henüz bir motif seçilmedi",
    mq_clear: "Sorguyu temizle",
    mq_query_retired: "Sorgu dilinin parçası olmaktan çıkarıldı ve yok sayıldı: {tokens}. Değiştirilmiş konumlar artık sorulmak yerine her hücrede işaretlenir ve reseptör ayrıntısında listelenir.",
    mq_empty_prompt: "Başlamak için bir konumda bir kalıntı isteyin: yukarıya yazın, aşağıdaki konum başvurusunu açıp bir dağılımdan seçin ya da aşağıdaki satırdan bir motifi başlangıç noktası alıp düzenleyin.",
    mq_asked_for: "İSTENEN",
    mq_receptor_frequency: "RESEPTÖR SIKLIĞI",
    mq_frequency_help: "Bu kapsamdaki reseptörlerin, bu konumda istenen kalıntılardan birini kendi yabanıl tip dizisinde hâlihazırda taşıyanlarının oranı. Yüksek bir oran, konumun neredeyse hiçbir şeyi ayırmadığı anlamına gelir: hemen her reseptör eşleşir, dolayısıyla oradaki bir eşleşme belirli bir reseptör hakkında kanıt değildir. Yapılar değil, reseptörler sayılır.",
    mq_entropy: "ENTROPİ",
    mq_entropy_help: "Bu konumdaki kalıntı dağılımının reseptörler üzerinden hesaplanan Shannon entropisi (bit). Sıfır, bu kapsamdaki her reseptörün orada aynı kalıntıyı taşıdığını gösterir; daha yüksek değerler konumun değişken olduğu, dolayısıyla oraya ilişkin bir sorunun reseptörleri birbirinden ayırdığı anlamına gelir.",
    mq_weight: "AĞIRLIK",
    mq_weight_help: "Pozisyonun değişkenliğine (entropisine) göre belirlenen önem derecesidir. Bütün reseptörlerde ortak olan sıradan kalıntılar düşük ağırlık alırken, aileleri birbirinden ayıran değişken pozisyonlar skora daha yüksek katkı sağlar. Değer 0 ile 1 arasındadır: havuzdaki en az değişken konum 0, en değişken konum 1 alır. Bu ağırlık yalnızca AĞIRLIKLI sütununda kullanılır; BİREBİR sütununda bütün konumlar eşit sayılır.",
    mq_bits: "bit",
    mq_low_specificity: "düşük ayırt edicilik",
    mq_all_low_specificity: "Bu sorgudaki her konum, bu kapsamdaki reseptörlerin %90'ından fazlasının zaten taşıdığı bir kalıntıyı istiyor. Böyle bir sorgu neredeyse hiçbir şeyi ayırmaz: reseptörlerin çoğu yüksek skor alır ve aşağıdaki sıralama hiçbiri hakkında fazla bir şey söylemez. Aşağıda önerilen yüksek entropili konumlardan birinin eklenmesi sorguyu ayırt edici kılar.",
    mq_suggest: "Henüz sorulmamış, entropisi daha yüksek konumlar:",
    mq_suggest_hint: "{position} konumunu sorguya ekle. {bits} bit taşır, yani mevcut sorgunun ayırmadığı reseptörleri ayırır.",
    mq_positions_open: "Konum başvurusu — 21 motif konumunun tümü, reseptör dağılımları ve entropileri",
    mq_family_ranking: "Aile sıralaması",
